export default function UserOrders({ orders }) {
  return (
    <div className="orders">
      <h3>Your Orders</h3>

      {orders.map(order => (
        <div key={order.orderId} className="order-card">
          <h4>Order ID: {order.orderId}</h4>
          <p>Status: {order.status}</p>
          <p>Total: ₹{order.total}</p>
        </div>
      ))}
    </div>
  );
}
